import { productAttrsApi, productSaveStocksApi } from "@/api/product.js";
export default {
  name: "stockEdit",
  props: {},
  data() {
    return {
      id: 0,
      specType: 0,
      batchShow: false,
      batchStock: 0,
      batchPm: 1,
      modals: false,
      loading: false,
      stockData: [],
      columns: [
        {
          title: "图片",
          slot: "image",
          minWidth: 20,
        },
        {
          title: "产品规格",
          key: "suk",
          minWidth: 90,
        },
        {
          title: "商品条形码",
          key: "bar_code",
          minWidth: 35,
        },
        {
          title: "商品编码",
          key: "code",
          minWidth: 35,
        },
        {
          title: "当前库存",
          key: "stock",
          minWidth: 10,
        },
        {
          title: "入/出库数量",
          slot: "num",
          minWidth: 200,
        },
      ],
    };
  },
  methods: {
    // 批量设置；
    countBatch() {
      this.batchStock = Math.abs(this.batchStock);
      this.stockData.forEach((item) => {
        item.changeNum = this.batchStock;
        if (this.batchPm) {
          item.pm = 1;
          item.resultNum = parseInt(item.stock) + parseInt(item.changeNum);
        } else {
          item.pm = 0;
          if (parseInt(item.stock) <= 0) {
            item.resultNum = 0;
          } else {
            let num = parseInt(item.stock) - parseInt(item.changeNum);
            item.resultNum = num <= 0 ? 0 : num;
          }
        }
      });
    },
    // 批量加减库存
    inputTap() {
      this.batchStock = this.batchStock.replace(/^\d{10}$/g, "0");
      this.countBatch();
    },
    // 批量设置入库或是出库
    batchStockTap() {
      this.countBatch();
    },
    // 单个设置
    countStock(row) {
      if (row.pm) {
        row.resultNum = parseInt(row.stock) + parseInt(row.changeNum);
      } else {
        if (parseInt(row.stock) <= 0) {
          row.resultNum = 0;
        } else {
          let num = parseInt(row.stock) - parseInt(row.changeNum);
          row.resultNum = num <= 0 ? 0 : num;
        }
      }
      this.stockData.forEach((item) => {
        if (row.id == item.id) {
          item.changeNum = row.changeNum;
          item.resultNum = row.resultNum;
          item.pm = row.pm;
        }
      });
    },
    // 设置加减库存
    stockTap(row) {
      this.countStock(row);
    },
    // 设置入库或是出库
    changeTap(row) {
      row.changeNum = row.changeNum.replace(/^\d{10}$/g, "0");
      this.countStock(row);
    },
    batchTap() {
      this.batchShow = !this.batchShow;
    },
    productAttrs(data) {
      this.specType = data.spec_type;
      this.id = data.id;
      productAttrsApi(data.id)
        .then((res) => {
          let data = res.data;
          data.forEach((item) => {
            item.resultNum = item.stock;
            item.changeNum = 0;
            item.pm = 1;
          });
          this.stockData = data;
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    productSaveStocks() {
      let attrs = [];
      this.stockData.forEach((item) => {
        let data = {
          unique: item.unique,
          pm: item.pm,
          stock: item.changeNum,
        };
        attrs.push(data);
      });
      productSaveStocksApi({ attrs: attrs }, this.id)
        .then((res) => {
          this.$Message.success("修改成功");
          this.cancel();
          this.$emit("stockChange", res.data.stock);
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    cancel() {
      this.modals = false;
      this.batchShow = false;
      this.batchPm = 1;
      this.batchStock = 0;
    },
  },
};
